// GENERATED by scripts/sync-engine.mjs from scrabbleio-server/src/engine — do not edit here.
// Move analysis: geometry, word extraction and scoring.
// Pure and dictionary-free, so the client can use it to preview a move's score
// with exactly the same rules the server uses to commit it.

import { BOARD_SIZE, CENTER, RACK_SIZE, BINGO_BONUS, PREMIUM_MULTIPLIERS, premiumAt } from './constants.js';

/**
 * @typedef {{ letter: string, value: number, joker: boolean }} Tile
 * @typedef {(Tile & Record<string, unknown>) | null} Cell
 * @typedef {{ x: number, y: number, letter: string, value: number, joker?: boolean }} Placement
 * @typedef {{ x: number, y: number, letter: string, value: number, joker: boolean, isNew: boolean, premium: string | null }} WordCell
 * @typedef {{ word: string, score: number, dir: 'H' | 'V', cells: WordCell[] }} ScoredWord
 * @typedef {{ ok: true, words: ScoredWord[], score: number, bingo: boolean }
 *         | { ok: false, error: string }} MoveAnalysis
 */

const AXES = { H: [1, 0], V: [0, 1] };

export function inBounds(x, y) {
  return Number.isInteger(x) && Number.isInteger(y) && x >= 0 && y >= 0 && x < BOARD_SIZE && y < BOARD_SIZE;
}

export function createEmptyBoard() {
  return Array.from({ length: BOARD_SIZE }, () => Array.from({ length: BOARD_SIZE }, () => null));
}

export function isBoardEmpty(board) {
  return board.every((row) => row.every((cell) => !cell));
}

const fail = (error) => ({ ok: false, error });
const key = (x, y) => `${x},${y}`;

/**
 * Validates the geometry of a move and scores every word it forms.
 * Does NOT check words against a dictionary.
 *
 * @param {Cell[][]} board
 * @param {Placement[]} placements
 * @returns {MoveAnalysis}
 */
export function analyzeMove(board, placements) {
  if (!Array.isArray(placements) || placements.length === 0) return fail('NO_TILES');
  if (placements.length > RACK_SIZE) return fail('TOO_MANY_TILES');

  const placed = new Map();
  for (const p of placements) {
    if (!inBounds(p.x, p.y)) return fail('OUT_OF_BOUNDS');
    if (board[p.y][p.x]) return fail('CELL_OCCUPIED');
    const k = key(p.x, p.y);
    if (placed.has(k)) return fail('DUPLICATE_CELL');
    placed.set(k, p);
  }

  let dir = null;
  if (placements.length > 1) {
    if (placements.every((p) => p.y === placements[0].y)) dir = 'H';
    else if (placements.every((p) => p.x === placements[0].x)) dir = 'V';
    else return fail('NOT_ALIGNED');
  }

  const tileAt = (x, y) => {
    if (!inBounds(x, y)) return null;
    const p = placed.get(key(x, y));
    if (p) return { letter: p.letter, value: p.value, joker: !!p.joker, isNew: true };
    const c = board[y][x];
    return c ? { letter: c.letter, value: c.value, joker: !!c.joker, isNew: false } : null;
  };

  // No holes between the first and the last placed tile.
  if (dir) {
    const [dx, dy] = AXES[dir];
    const sorted = [...placements].sort((a, b) => (a.x - b.x) + (a.y - b.y));
    const first = sorted[0];
    const last = sorted[sorted.length - 1];
    for (let x = first.x, y = first.y; x !== last.x + dx || y !== last.y + dy; x += dx, y += dy) {
      if (!tileAt(x, y)) return fail('NOT_CONTIGUOUS');
    }
  }

  const firstMove = isBoardEmpty(board);
  if (firstMove && !placed.has(key(CENTER, CENTER))) return fail('MUST_COVER_CENTER');

  // Every word of 2+ letters that runs through a newly placed tile, on both axes.
  const words = [];
  const seen = new Set();
  for (const p of placements) {
    for (const axis of ['H', 'V']) {
      const [dx, dy] = AXES[axis];
      let sx = p.x;
      let sy = p.y;
      while (tileAt(sx - dx, sy - dy)) { sx -= dx; sy -= dy; }
      const id = `${axis}:${sx},${sy}`;
      if (seen.has(id)) continue;
      seen.add(id);
      const cells = [];
      for (let x = sx, y = sy; tileAt(x, y); x += dx, y += dy) {
        cells.push({ x, y, ...tileAt(x, y), premium: null });
      }
      if (cells.length < 2) continue;
      for (const c of cells) if (c.isNew) c.premium = premiumAt(c.x, c.y);
      words.push({ word: cells.map((c) => c.letter).join(''), dir: axis, cells, score: scoreCells(cells) });
    }
  }

  if (words.length === 0) return fail(firstMove ? 'WORD_TOO_SHORT' : 'NOT_CONNECTED');
  if (!firstMove && !words.some((w) => w.cells.some((c) => !c.isNew))) return fail('NOT_CONNECTED');

  // Main word first: the one along the move's direction, or the longest for a single tile.
  words.sort((a, b) => {
    if (dir) return (b.dir === dir) - (a.dir === dir);
    return b.cells.length - a.cells.length;
  });

  const bingo = placements.length === RACK_SIZE;
  const score = words.reduce((sum, w) => sum + w.score, 0) + (bingo ? BINGO_BONUS : 0);
  return { ok: true, words, score, bingo };
}

function scoreCells(cells) {
  let sum = 0;
  let wordMultiplier = 1;
  for (const c of cells) {
    const m = (c.isNew && c.premium && PREMIUM_MULTIPLIERS[c.premium]) || { letter: 1, word: 1 };
    sum += c.value * m.letter;
    wordMultiplier *= m.word;
  }
  return sum * wordMultiplier;
}
